/* Loads ??? (Hatena) blue magic resources. */
// FUNCTION: FF7 0x00571e20
void __cdecl BattleFx_BlueLoadResQuestionMarks(void)
{
    GfxModelTableBank *stage;
    GfxResourceRequest reqBuffer;
    int kind;
    char nameWorkBuffer[200];
    GfxResourceRequest *pRequest;
    int resourceDefsWord;

    if (g_pBattle3dScene != 0 && g_BattleBlueQuestionMarksLoadedResTable == 0) {
        kind = 2;
        resourceDefsWord = (int)&g_BattleBlueQuestionMarksResourceDefs;
        stage = (GfxModelTableBank *)(g_pBattle3dScene->modelTableBank);
        pRequest = &reqBuffer;
        Gfx_InitResourceRequest(pRequest);
        pRequest->groupTag = 0;
        // STRING: FF7 0x008abd3c
        pRequest->resourcePath = BattleFx_BuildResourcePath("blue/hatena", nameWorkBuffer);
        Gfx_LoadModelTableIfAbsent(kind, resourceDefsWord, pRequest, &g_BattleBlueQuestionMarksLoadedResTable, stage);
    }
}

