/* Initializes setup task for ??? (Hatena). */
// FUNCTION: FF7 0x00571eca
void __cdecl BattleFx_BlueBeginQuestionMarks(int targetMask, int actorIdx)
{
    int idx, count;

    *(int *)&g_BattleFxDrawListBufferTaskSlotPtr = (int)BATTLE_NEW_TASK_SLOT(BattleFx_SelectDrawListBuffer);
    idx = 0;
    for (count = 0; idx < 10; idx++) {
        if ((targetMask & 1 << idx) != 0) {
            count++;
            if (count == 1) {
                g_BattleBlueQuestionMarksTargetIndex = idx;
            }
        }
    }
    Battle_AllocateResourceSlot(BattleFx_BlueQuestionMarksSetupTask);
    Battle_DispatchSfxOpcodeDirect(SOUND_SFX_PLAY_1, Battle_ComputePanForEntity(targetMask), 0x85);
}

