/* Spawns drifting question mark sprite particles. */
// FUNCTION: FF7 0x00572912
void __cdecl BattleFx_BlueQuestionMarksSpawnDriftingSpritesTask(void)
{
    VECTOR nx;
    int i;
    int pace;
    int radius;
    BattleFxQuestionMarksDrifter *spawner;
    BattleFxQuestionMarksDriftSprite *pDriftSprite;

    spawner = (BattleFxQuestionMarksDrifter *)BATTLE_CURRENT_TASK_SLOT;
    if (g_BattleIsPaused != 0) {
        return;
    }
    if (spawner->step >= 6 && spawner->step <= 9) {
        for (i = 0; i < 20; i++) {
            pDriftSprite = (BattleFxQuestionMarksDriftSprite *)BATTLE_NEW_TASK_SLOT(BattleFx_BlueQuestionMarksDriftingAnimatedSpriteTask);
            nx.vx = rand() % 1800 - 900;
            nx.vy = 0;
            nx.vz = rand() % 1800 - 900;
            NormalizeVectorFixed(&nx, &nx);
            radius = rand() % 400 + 600;
            pDriftSprite->posX = spawner->posX + (radius * nx.vx >> 12);
            pDriftSprite->posY = 0;
            pDriftSprite->posZ = spawner->posZ + (radius * nx.vz >> 12);
            pDriftSprite->scale = spawner->spriteScale;
            pace = rand() % 32 + 100;
            pDriftSprite->velocityX = pace * nx.vx >> 12;
            pDriftSprite->velocityZ = pace * nx.vz >> 12;
        }
    }
    if (spawner->step >= 24) {
        spawner->ownerSlot = BATTLE_TASK_FREE;
    }
    (spawner->step)++;
}

/* Animates and submits drifting question mark sprite. */
// FUNCTION: FF7 0x00572a9f
void __cdecl BattleFx_BlueQuestionMarksDriftingAnimatedSpriteTask(void)
{
    BattleFxQuestionMarksDriftSprite *task;

    task = (BattleFxQuestionMarksDriftSprite *)BATTLE_CURRENT_TASK_SLOT;
    g_BattleBlueQuestionMarksSpriteReq.frame = task->timer;
    BattleFx_InstallBillboardMatrix(&task->posX, (short)task->scale, 0);
    g_BattleBlueQuestionMarksSpriteReq.spriteGroup = (BattleFxSpriteGroup *)Gfx_ModelTableGetLoadedRecord(1, g_BattleBlueQuestionMarksLoadedResTable);
    g_BattleBlueQuestionMarksSpriteReq.drawObj = Gfx_ModelTableGetSpriteObject(1, g_BattleBlueQuestionMarksLoadedResTable);
    g_BattleFxActiveDrawListPtr = BattleFx_SubmitSpriteDraw(&g_BattleBlueQuestionMarksSpriteReq.spriteGroup, g_BattleCurrentOrderingTable + BATTLE_OT_DEPTH_SORTED, 0xC, g_BattleFxActiveDrawListPtr);
    if (task->timer >= 11) {
        task->ownerSlot = BATTLE_TASK_FREE;
    }
    if (g_BattleIsPaused != 0) {
        return;
    }
    task->posX += task->velocityX;
    task->posZ += task->velocityZ;
    (task->timer)++;
}
